    int i;
    int entries;

    if (!c->nb_streams) {
        return AVERROR_INVALIDDATA;
    }

    entries = avio_rb32(pb); // Read number of entries
    if (entries <= 0) {
        return 0;
    }

    for (i = 0; i < entries; i++) {
        uint32_t type;
        uint16_t version, flags;
        int size;

        type = avio_rl32(pb);
        avio_rb16(pb); // skip version
        avio_rb16(pb); // skip flags

        size = avio_rb32(pb); // Read size of entry

        if (type == MKTAG('a','l','i','a')) {
            // Handle Macintosh alias record
            avio_skip(pb, 4); // Skip alias length
            avio_skip(pb, 4); // Skip offset
            // Read alias data as necessary
        } else if (type == MKTAG('u','r','l',' ')) {
            uint8_t is_self_referencing;

            is_self_referencing = avio_r8(pb);
            // Handle URL based reference
        } else {
            // Skip unknown or unsupported types
            avio_skip(pb, size - 4); // Skip the rest of the entry
        }
    }

    return 0;
}

int mov_read_dref(MOVContext *c, AVIOContext *pb, MOVAtom atom) {
    int i;
    int entries;
    MOVDref *dref;

    if (!c->fc->nb_streams) {
        return 0;
    }

    entries = avio_rb32(pb); // number of entries
    if ((unsigned)entries > INT_MAX / sizeof(*dref))
        return AVERROR(ENOMEM);

    dref = av_malloc(entries * sizeof(*dref));
    if (!dref)
        return AVERROR(ENOMEM);

    for (i = 0; i < entries; i++) {
        dref[i].type = avio_rb32(pb);
        dref[i].size = avio_rb32(pb);

        if (dref[i].type == MKTAG('a','l','i','s')) {
            // Handle Macintosh alias records
            uint32_t alias_size = avio_rb32(pb);
            dref[i].alias_data = av_malloc(alias_size);
            if (!dref[i].alias_data) {
                av_freep(&dref);
                return AVERROR(ENOMEM);
            }
            avio_read(pb, dref[i].alias_data, alias_size);
        } else {
            // Skip data for other types
            avio_skip(pb, dref[i].size - 8);
        }

        dref[i].filename = NULL;
        dref[i].path = NULL;
    }

    return 0;
}

int mov_read_dref(MOVContext *c, AVIOContext *pb, MOVAtom atom) {
    int i;
    int entries;

    if (!c->nb_streams) {
        avio_skip(pb, atom.size);
        return 0;
    }

    entries = avio_rb32(pb);
    if (entries < 0 || atom.size < 4 + entries * 12) {
        return AVERROR_INVALIDDATA;
    }

    for (i = 0; i < entries; i++) {
        uint32_t type;
        int size;
        int volume;
        int filename_len;
        char *filename = NULL;

        type = avio_rl32(pb);
        size = avio_rb32(pb);
        volume = avio_rb16(pb);

        if (type == MKTAG('a','l','i','a')) {
            avio_skip(pb, 4);
            avio_rb32(pb); // skip name
            avio_skip(pb, 4);
            avio_skip(pb, 8);
            avio_skip(pb, 4);
        } else if (type == MKTAG('u','r','l',' ')) {
            int flags = avio_rb16(pb);
            if (!(flags & 1))
                avio_skip(pb, 1);
        } else {
            avio_skip(pb, 2);
        }

        avio_skip(pb, 8);

        filename_len = avio_get_str(pb, size - 20, NULL, 0);
        if (filename_len > 0) {
            filename = av_malloc(filename_len + 1);
            if (!filename)
                return AVERROR(ENOMEM);
            avio_get_str(pb, size - 20, filename, filename_len + 1);
        } else {
            avio_skip(pb, size - 20);
        }

        av_freep(&filename);
    }

    return 0;
}

int mov_read_dref(MOVContext *c, AVIOContext *pb, MOVAtom atom) {
    int i, entries;
    int64_t size;

    if (!c->nb_streams) {
        avio_skip(pb, atom.size);
        return 0;
    }

    entries = avio_rb32(pb);
    if (entries < 0)
        return AVERROR_INVALIDDATA;

    for (i = 0; i < entries; i++) {
        int64_t pos = avio_tell(pb);
        int type;
        uint32_t flags;

        if (avio_feof(pb))
            return AVERROR_EOF;

        type = avio_rl32(pb);
        avio_skip(pb, 4); // skip data size
        flags = avio_rb32(pb);

        if (type == MKTAG('a','l','i','a')) {
            uint32_t alias_size = avio_rb32(pb);
            if (alias_size > atom.size)
                return AVERROR_INVALIDDATA;

            avio_skip(pb, alias_size - 4);
        } else if (type == MKTAG('u','r','l',' ')) {
            int has_filename = flags & 1;
            avio_skip(pb, 1); // skip name
            if (has_filename) {
                size = avio_size(pb);
                if (size <= 0)
                    return AVERROR_INVALIDDATA;
            }
        } else {
            avio_skip(pb, 4); // skip volume
            avio_skip(pb, 4); // skip directory
        }

        avio_seek(pb, pos + atom.size, SEEK_SET);
    }

    return 0;
}

int mov_read_dref(MOVContext *c, AVIOContext *pb, MOVAtom atom) {
    int i, entries;
    MOVTrack *track;

    if (!c->tracks) {
        return AVERROR_INVALIDDATA;
    }

    entries = avio_rb32(pb); // Read number of entries
    if (entries < 0)
        return AVERROR_INVALIDDATA;

    for (i = 0; i < entries; i++) {
        int size = avio_rb32(pb);
        int type = avio_rl32(pb);

        switch (type) {
            case MKTAG('u','r','l',' ') : {
                int flags = avio_rb32(pb);
                if (flags & 1) {
                    char *filename = av_malloc(size - 8);
                    if (!filename)
                        return AVERROR(ENOMEM);
                    avio_get_str(pb, size - 8, filename, size - 8);
                    // Process filename
                    av_free(filename);
                }
                break;
            }
            case MKTAG('m','a','c',' ') : {
                // Macintosh alias record handling
                avio_skip(pb, size - 4);
                break;
            }
            default:
                avio_skip(pb, size - 4);
        }
    }

    return 0;
}
